                const sectionTop = section.offsetTop;
                const sectionHeight = section.clientHeight;
                if (window.scrollY >= sectionTop - 100 && window.scrollY < sectionTop + sectionHeight - 100) {
                    currentSection = section.getAttribute('id');
                }
            });

            navLinks.forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('href') === '#' + currentSection) {
                    link.classList.add('active');
                }
            });
        });

        // Scroll Reveal
        const revealElements = document.querySelectorAll('.reveal');

        const revealOnScroll = () => {
            revealElements.forEach(element => {
                const elementTop = element.getBoundingClientRect().top;
                const elementVisible = 150;

                if (elementTop < window.innerHeight - elementVisible) {
                    element.classList.add('visible');
                }
            });
        };

        window.addEventListener('scroll', revealOnScroll);
        window.addEventListener('load', revealOnScroll);

        // Artist Modal
        const modalButtons = document.querySelectorAll('.view-details-btn');
        const modals = document.querySelectorAll('.modal');
        const closeButtons = document.querySelectorAll('.close-modal');

        modalButtons.forEach(button => {
            button.addEventListener('click', function() {
                const modalId = this.getAttribute('data-modal');
                const modal = document.getElementById(modalId);
                modal.style.display = 'flex';
            });
        });

        closeButtons.forEach(button => {
            button.addEventListener('click', function() {
                this.closest('.modal').style.display = 'none';
            });
        });

        window.addEventListener('click', function(e) {
            modals.forEach(modal => {
                if (e.target === modal) {
                    modal.style.display = 'none';
                }
            });
        });

        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                modals.forEach(modal => {
                    modal.style.display = 'none';
                });
            }
        });

        // Ticket Tier Selection
        const selectTierButtons = document.querySelectorAll('.select-tier-btn');
        const ticketModal = document.getElementById('ticket-modal');
        const selectedTierDisplay = document.getElementById('selected-tier');
        const ticketForm = document.getElementById('ticket-form');
        const closeTicketModal = ticketModal.querySelector('.close-modal');

        selectTierButtons.forEach(button => {
            button.addEventListener('click', function() {
                const tier = this.getAttribute('data-tier');
                let tierName = '';
                switch(tier) {
                    case 'night':
                        tierName = 'Night Pass (€29)';
                        break;
                    case 'curator':
                        tierName = 'Curator Pass (€59)';
                        break;
                    case 'patron':
                        tierName = 'Patron Pass (€129)';
                        break;
                }
                selectedTierDisplay.textContent = 'Selected Tier: ' + tierName;
                ticketModal.style.display = 'flex';
            });
        });

        closeTicketModal.addEventListener('click', function() {
            ticketModal.style.display = 'none';
        });

        window.addEventListener('click', function(e) {
            if (e.target === ticketModal) {
                ticketModal.style.display = 'none';
            }
        });

        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                ticketModal.style.display = 'none';
            }
        });

        // Ticket Form Validation
        ticketForm.addEventListener('submit', function(e) {
            e.preventDefault();
            const name = document.getElementById('attendee-name').value;
            const email = document.getElementById('attendee-email').value;
            const quantity = document.getElementById('ticket-quantity').value;
            const terms = document.getElementById('terms').checked;

            if (!terms) {
                alert('Please accept the terms and conditions.');
                return;
            }

            // Simulate success
            const toast = document.getElementById('toast');
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);

            // Reset form
            ticketForm.reset();
            ticketModal.style.display = 'none';
        });

        // Newsletter Form Validation
        const newsletterForm = document.getElementById('newsletter-form');
        const newsletterError = document.getElementById('newsletter-error');

        newsletterForm.addEventListener('submit', function(e) {
            e.preventDefault();
            const email = document.getElementById('newsletter-email').value;
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (!emailRegex.test(email)) {
                newsletterError.style.display = 'block';
                return;
            }

            newsletterError.style.display = 'none';
            const toast = document.getElementById('toast');
            toast.textContent = 'Thank you for subscribing!';
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
            newsletterForm.reset();
        });

        // Save to Calendar
        document.getElementById('save-calendar').addEventListener('click', function() {
            const icsContent = `BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//ARTIFACT//EN
CALSCALE:GREGORIAN
BEGIN:VEVENT
UID:artifact-museum-night-2026
DTSTAMP:20261018T000000Z
DTSTART:20261018T190000Z
DTEND:20261019T020000Z
SUMMARY:ARTIFACT: Museum Night
DESCRIPTION:A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.
LOCATION:The Old Gallery, Warsaw
END:VEVENT
END:VCALENDAR`;

            const blob = new Blob([icsContent], { type: 'text/calendar' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'artifact-museum-night.ics';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            // Show toast
            const toast = document.getElementById('toast');
            toast.textContent = 'Calendar file downloaded!';
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        });
    </script>
</body>
